template <typename Derived>
class StaticBase {
public:
    void interface() const {
        // Static dispatch via CRTP
        static_cast<const Derived*>(this)->specialized_op();
    }
};

class HandlerA : public StaticBase<HandlerA> {
public:
    void specialized_op() const {
        // Code Path A
    }
};

class HandlerB : public StaticBase<HandlerB> {
public:
    void specialized_op() const {
        // Code Path B
    }
};

// Compiler selects specialized_op based on Derived type at compile time.
// (No virtual overhead)
